<?php
 namespace Pterodactyl\Services\Dezerx; class Text { public static function utf8(string $text): string { if (preg_match('//u', $text) === 1) { return $text; } return mb_convert_encoding($text, 'UTF-8', 'UTF-8'); } public static function summary(string $text, int $limit = 120): string { $text = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8'); $text = strip_tags($text); $text = preg_replace('/[*_`#>\[\]]+/u', '', $text) ?? $text; $text = preg_replace('/\s+/u', ' ', $text) ?? $text; $text = trim($text); if (mb_strwidth($text, 'UTF-8') <= $limit) { return $text; } $cut = mb_strimwidth($text, 0, $limit, '', 'UTF-8'); $space = mb_strrpos($cut, ' '); if ($space !== false && $space > mb_strlen($cut) * 0.6) { $cut = mb_substr($cut, 0, $space); } return rtrim($cut, " \t\n\r\0\x0B.,;:").'…'; } } 